import sys
from math import gcd

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    t = int(next(iterator))

    results = []

    for _ in range(t):
        n = int(next(iterator))
        m = int(next(iterator))

        a = []
        for _ in range(n):
            a.append(int(next(iterator)))

        B = []
        for _ in range(m):
            B.append(int(next(iterator)))

        g = 0
        for b in B:
            g = gcd(g, b)
        g = gcd(g, n)

        total_abs = 0
        min_abs = float('inf')
        neg_count = 0

        for x in a:
            val = abs(x)
            total_abs += val
            if val < min_abs:
                min_abs = val
            if x < 0:
                neg_count += 1

        for i in range(0, n, g):
            group_neg = 0
            group_min = float('inf')
            for j in range(i, i + g):
                if j >= n:
                    break
                if a[j] < 0:
                    group_neg += 1
                if abs(a[j]) < group_min:
                    group_min = abs(a[j])

            if group_neg % 2 == 1:
                total_abs -= 2 * group_min

        results.append(str(total_abs))

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == '__main__':
    solve()
